--
-- Dumping routines for database 'lumiere'
--
/*!50003 DROP FUNCTION IF EXISTS `check_product_stock` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = cp850 */ ;
/*!50003 SET character_set_results = cp850 */ ;
/*!50003 SET collation_connection  = cp850_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `check_product_stock`(input_product_id INT) RETURNS varchar(300) CHARSET utf8mb4
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE result VARCHAR(300);

    SELECT CONCAT(product_name, ' | Stock: ', inventory_count)
    INTO result
    FROM product
    WHERE product_id = input_product_id
    LIMIT 1;

    RETURN IFNULL(result, 'Product not found');
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `add_to_cart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `add_to_cart`(
    IN p_cust_id INT,
    IN p_prod_id INT,
    IN p_qty INT
)
BEGIN
    -- Cek apakah barang sudah ada di keranjang customer tersebut
    IF EXISTS (SELECT 1 FROM cart WHERE customer_id = p_cust_id AND product_id = p_prod_id) THEN
        -- Jika sudah ada, tambahkan jumlahnya (akumulasi)
        UPDATE cart 
        SET qty = qty + p_qty 
        WHERE customer_id = p_cust_id AND product_id = p_prod_id;
    ELSE
        -- Jika belum ada, masukkan baris baru
        INSERT INTO cart (customer_id, product_id, qty) 
        VALUES (p_cust_id, p_prod_id, p_qty);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
