CREATE DEFINER=`root`@`localhost` PROCEDURE `get_customer_cart`(IN input_customer_id INT)
BEGIN
    SELECT 
        c.cart_id,
        c.customer_id,
        c.product_id,
        p.product_name,
        c.qty,
        p.price,
        (c.qty * p.price) AS total_price
    FROM cart c
    JOIN product p ON c.product_id = p.product_id
    WHERE c.customer_id = input_customer_id;
END ;;
DELIMITER ;
