CREATE DEFINER=`root`@`localhost` PROCEDURE `update_cart`(
    IN p_cust_id INT,
    IN p_prod_id INT,
    IN p_new_qty INT
)
BEGIN
    IF p_new_qty > 0 THEN
        -- Update jumlah jika lebih dari 0
        UPDATE cart 
        SET qty = p_new_qty 
        WHERE customer_id = p_cust_id AND product_id = p_prod_id;
    ELSE
        -- Jika diatur ke 0, otomatis hapus dari keranjang
        DELETE FROM cart 
        WHERE customer_id = p_cust_id AND product_id = p_prod_id;
    END IF;
END ;;
DELIMITER ;
